package handlers

import "testing"

func TestCreateUser_valid(t *testing.T) {
	if err := CreateUser(User{Name: "Alice", Email: "a@b.com"}); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestCreateUser_missing_name(t *testing.T) {
	if err := CreateUser(User{Email: "a@b.com"}); err == nil {
		t.Fatal("expected error for missing name")
	}
}

func TestCreateUser_missing_email(t *testing.T) {
	if err := CreateUser(User{Name: "Alice"}); err == nil {
		t.Fatal("expected error for missing email")
	}
}

func TestUpdateUser_valid(t *testing.T) {
	if err := UpdateUser(User{Name: "Bob", Email: "b@c.com"}); err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
}

func TestUpdateUser_missing_name(t *testing.T) {
	if err := UpdateUser(User{Email: "b@c.com"}); err == nil {
		t.Fatal("expected error for missing name")
	}
}

func TestUpdateUser_missing_email(t *testing.T) {
	if err := UpdateUser(User{Name: "Bob"}); err == nil {
		t.Fatal("expected error for missing email")
	}
}
